LLMResponse(content='def wrap(text, cols):
    lines = []

    if cols <= 0:
        raise ValueError("cols must be greater than 0")

    text = text.strip()

    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = cols
            line, text = text[:end], text[end:]
        else:
            line, text = text[:end], text[end + 1:]

        lines.append(line.strip())
        text = text.lstrip()

    if text:
